; Block: p8b_txt

p8b_txt:

; ---- Subroutine: p8b_txt.p8s_chrout ----
    ALIGN 2

p8b_txt.p8s_chrout:
            move.l  sys.DOSBase,a6
            move.b  d0,-(sp)          ; 1. Push character onto the stack. A7 now points to it!
            move.l  4.w,a0
            cmp.w   #36,20(a0)      ; KS 2.0 = V36
            bcc.s   .use_writechars

            jsr     -60(a6)           ; Output()
            move.l  d0, d1
            move.l  sp, d2             ; D2 = Pointer to our character (Current Stack Pointer)
            moveq   #1, d3             ; D3 = We only want to write exactly 1 byte
            jsr     -48(a6)           ; Write()
            addq.l  #2, sp
            rts

.use_writechars:
            move.l  sp, d1
            moveq   #1, d2
            jsr     -942(a6)        ; WriteChars (ks 2.0+)
            addq.l  #2, sp
            rts
; End of subroutine: p8b_txt.p8s_chrout

; ---- Subroutine: p8b_txt.p8s_nl ----
; source: textio.p8:34

    ALIGN 2

p8b_txt.p8s_nl:
        ; load.b r279.b,#10.b
        ; call p8b_txt.p8s_chrout(r279.b@s10)
    moveq  #10,d0
    bsr  p8b_txt.p8s_chrout
        ; return
    rts
; End of subroutine: p8b_txt.p8s_nl

